// Random Reels 15, the whole app in one file: server and website together.
// Random Reels server: accounts, posts, stories, messages and uploaded media in one file.
// No dependencies, needs Node 18 or newer.   Run it with:  node server.js   then open http://localhost:3000
const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto');
const PORT = +process.env.PORT || 3000, HOST = process.env.HOST || '0.0.0.0';
const DIR = process.env.DATA_DIR || path.join(__dirname, 'data'), MEDIA = path.join(DIR, 'media');
const MAX_JSON = 1 << 20, MAX_MEDIA = 80 << 20, COLS = ['users', 'posts', 'stories', 'msgs', 'comments', 'likes'];
fs.mkdirSync(MEDIA, {recursive: true});

const load = f => { try { return JSON.parse(fs.readFileSync(path.join(DIR, f), 'utf8')); } catch (e) { return null; } };
const db = Object.assign({users: {}, posts: {}, stories: {}, msgs: {}, comments: {}, likes: {}}, load('db.json'));
const auth = Object.assign({users: {}, tokens: {}}, load('auth.json'));
if (db._wipe !== 'v15') {   // one-time clean slate: every old account, post and file is removed
  for (const c of COLS) db[c] = {}; db._wipe = 'v15'; auth.users = {}; auth.tokens = {};
  try { for (const f of fs.readdirSync(MEDIA)) fs.unlinkSync(path.join(MEDIA, f)); } catch (e) {}
  try { fs.writeFileSync(path.join(DIR, 'db.json'), JSON.stringify(db)); fs.writeFileSync(path.join(DIR, 'auth.json'), JSON.stringify(auth)); } catch (e) {}
}
const timers = {};
const save = (f, obj) => {   // debounced, and written to a temp file first so a crash never leaves half a database
  clearTimeout(timers[f]);
  timers[f] = setTimeout(() => { const t = path.join(DIR, f + '.tmp'); fs.writeFile(t, JSON.stringify(obj), e => { if (!e) fs.rename(t, path.join(DIR, f), () => {}); }); }, 300);
};
const boot = crypto.randomBytes(3).toString('hex'), vers = {}; let counter = 0;
const ver = c => vers[c] || (vers[c] = boot + '-0'), bump = c => { vers[c] = boot + '-' + (++counter); save('db.json', db); };

const fail = (code, message) => Object.assign(new Error(message), {code});
const CORS = {'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'Authorization, Content-Type', 'Access-Control-Allow-Methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS'};
const send = (res, code, obj) => { res.writeHead(code, {...CORS, 'Content-Type': 'application/json'}); res.end(JSON.stringify(obj)); };
const readBody = (req, max) => new Promise((ok, no) => {
  const chunks = []; let n = 0;
  req.on('data', d => { n += d.length; if (n > max) { no(fail(413, 'That file is too big')); req.destroy(); } else chunks.push(d); });
  req.on('end', () => ok(Buffer.concat(chunks))); req.on('error', no);
});
const readJson = async req => { const b = await readBody(req, MAX_JSON); try { return JSON.parse(b.toString() || '{}'); } catch (e) { throw fail(400, 'Bad request'); } };

const sha = t => crypto.createHash('sha256').update(t).digest('hex');
const hashPw = (pw, salt) => crypto.scryptSync(pw, salt, 32).toString('hex');
const who = req => { const m = /^Bearer (.+)$/.exec(req.headers.authorization || ''), s = m && auth.tokens[sha(m[1])]; return s && s.exp > Date.now() ? s : null; };
const issue = (name, uid) => { const t = crypto.randomBytes(32).toString('hex'); auth.tokens[sha(t)] = {name, uid, exp: Date.now() + 90 * 864e5}; save('auth.json', auth); return t; };
const clean = s => String(s || '').toLowerCase().replace(/[^a-z0-9._]/g, '');
const text = (s, n) => String(s || '').slice(0, n);
const strikes = new Map();   // failed logins per address, to slow down password guessing
const blocked = ip => (strikes.get(ip) || []).filter(t => t > Date.now() - 6e5).length >= 10;
const strike = ip => strikes.set(ip, [...(strikes.get(ip) || []).filter(t => t > Date.now() - 6e5), Date.now()]);
const strip = ({_o, ...d}) => d;

async function api(req, res, url) {
  const ip = req.socket.remoteAddress, s = who(req), m = req.method;
  if (url.pathname === '/api/ping') return send(res, 200, {rr: 1});
  if (url.pathname === '/api/me') return s ? send(res, 200, {name: s.name, uid: s.uid}) : send(res, 401, {error: 'Please log in again'});
  if (url.pathname === '/api/mydata') {   // each account's private data (notes, history, skins...), so you can log back in anywhere
    if (!s) throw fail(401, 'Please log in again'); const a = auth.users[s.name]; if (!a) throw fail(404, 'No such account');
    if (m === 'GET') return send(res, 200, {data: a.data || null});
    if (m === 'PUT') { const b = await readJson(req); a.data = b.data || null; save('auth.json', auth); return send(res, 200, {ok: 1}); }
    throw fail(405, 'Method not allowed');
  }
  if (url.pathname === '/api/signup' && m === 'POST') {
    const b = await readJson(req), n = clean(b.username);
    if (!/^[a-z0-9._]{3,14}$/.test(n)) throw fail(400, 'Usernames are 3 to 14 letters or numbers');
    if (String(b.password || '').length < 6) throw fail(400, 'Pick a password with at least 6 characters');
    if (auth.users[n]) throw fail(409, 'That username is taken. Try another.');
    const salt = crypto.randomBytes(16).toString('hex'), uid = crypto.randomBytes(8).toString('hex');
    auth.users[n] = {uid, salt, hash: hashPw(b.password, salt)};
    db.users[n] = {uid, display: text(b.display, 24), hue: +b.hue || 265, bio: '', t: Date.now(), _o: n}; bump('users');
    return send(res, 200, {token: issue(n, uid), uid, user: strip(db.users[n])});
  }
  if (url.pathname === '/api/login' && m === 'POST') {
    if (blocked(ip)) throw fail(429, 'Too many tries. Wait a few minutes.');
    const b = await readJson(req), n = clean(b.username), a = auth.users[n];
    const ok = a && crypto.timingSafeEqual(Buffer.from(hashPw(String(b.password || ''), a.salt), 'hex'), Buffer.from(a.hash, 'hex'));
    if (!ok) { strike(ip); throw fail(401, 'Wrong username or password'); }
    return send(res, 200, {token: issue(n, a.uid), uid: a.uid, user: strip(db.users[n] || {})});
  }
  if (url.pathname === '/api/upload' && m === 'POST') {
    if (!s) throw fail(401, 'Log in to upload');
    const type = String(req.headers['content-type'] || '').split(';')[0];
    if (!/^(video|image|audio)\//.test(type)) throw fail(415, 'Only videos, photos and audio can be uploaded');
    const id = crypto.randomBytes(12).toString('hex'), body = await readBody(req, MAX_MEDIA);
    await fs.promises.writeFile(path.join(MEDIA, id), body); await fs.promises.writeFile(path.join(MEDIA, id + '.type'), type);
    return send(res, 200, {id});
  }
  const d = /^\/api\/db\/(\w+)(?:\/([^/]+))?$/.exec(url.pathname);
  if (!d || !COLS.includes(d[1])) throw fail(404, 'not found');
  const col = d[1], id = d[2] && decodeURIComponent(d[2]), docs = db[col];
  if (m === 'GET' && !id) {
    if (col === 'msgs' && !s) throw fail(401, 'Log in to read messages');
    if (url.searchParams.get('ver') === ver(col)) return send(res, 200, {ver: ver(col)});   // nothing changed since the last poll
    const list = Object.entries(docs).filter(([, v]) => col !== 'msgs' || v.from === s.name || v.to === s.name).map(([k, v]) => ({id: k, data: strip(v)}));
    return send(res, 200, {ver: ver(col), docs: list});
  }
  if (m === 'GET') { const v = docs[id]; if (!v || (col === 'msgs' && !(s && (v.from === s.name || v.to === s.name)))) throw fail(404, 'not found'); return send(res, 200, strip(v)); }
  if (!s) throw fail(401, 'Log in first');
  const old = docs[id], mine = col === 'users' ? id === s.name : !old || old._o === s.name;
  if (!mine) throw fail(403, 'That belongs to someone else');
  if (m === 'DELETE') { if (col === 'users') throw fail(403, 'Accounts cannot be deleted here'); delete docs[id]; bump(col); return send(res, 200, {ok: 1}); }
  if (m !== 'PUT' && m !== 'PATCH') throw fail(405, 'Method not allowed');
  const b = await readJson(req);
  if (col === 'posts' || col === 'stories') { if (b.user !== s.name) throw fail(403, 'Posts must be made as yourself'); }
  if (col === 'likes') { if (b.u !== s.name) throw fail(403, 'Likes must be made as yourself'); b.rid = String(b.rid).slice(0, 60); }
  if (col === 'comments') { if (b.u !== s.name || old) throw fail(403, 'Comments must be made as yourself'); b.t = text(b.t, 200); }
  if (col === 'msgs') { if (b.from !== s.name || old) throw fail(403, 'Messages cannot be changed'); b.t = text(b.t, 500); }
  const next = m === 'PATCH' && old ? {...old, ...b} : b;
  docs[id] = {...next, _o: s.name, ...(col === 'users' ? {uid: s.uid} : {})};
  bump(col); return send(res, 200, {ok: 1});
}

function media(req, res, id) {
  const file = path.join(MEDIA, id);
  fs.stat(file, (e, st) => {
    if (e) return send(res, 404, {error: 'not found'});
    let type = 'application/octet-stream'; try { type = fs.readFileSync(file + '.type', 'utf8'); } catch (x) {}
    const r = /bytes=(\d*)-(\d*)/.exec(req.headers.range || ''); let start = 0, end = st.size - 1;
    if (r) { if (r[1]) { start = +r[1]; if (r[2]) end = Math.min(end, +r[2]); } else if (r[2]) start = Math.max(0, st.size - +r[2]); }
    if (start > end) { res.writeHead(416, {...CORS, 'Content-Range': 'bytes */' + st.size}); return res.end(); }
    res.writeHead(r ? 206 : 200, {...CORS, 'Content-Type': type, 'Accept-Ranges': 'bytes', 'Content-Length': end - start + 1, 'Cache-Control': 'public, max-age=31536000, immutable', ...(r ? {'Content-Range': `bytes ${start}-${end}/${st.size}`} : {})});
    fs.createReadStream(file, {start, end}).pipe(res);
  });
}

function audio(req, res, buf) {
  const r = /bytes=(\d*)-(\d*)/.exec(req.headers.range || ''); let start = 0, end = buf.length - 1;
  if (r) { if (r[1]) { start = +r[1]; if (r[2]) end = Math.min(end, +r[2]); } else if (r[2]) start = Math.max(0, buf.length - +r[2]); }
  if (start > end) { res.writeHead(416, {'Content-Range': 'bytes */' + buf.length}); return res.end(); }
  res.writeHead(r ? 206 : 200, {'Content-Type': 'audio/mpeg', 'Accept-Ranges': 'bytes', 'Content-Length': end - start + 1, 'Cache-Control': 'public, max-age=31536000, immutable', ...(r ? {'Content-Range': `bytes ${start}-${end}/${buf.length}`} : {})});
  res.end(buf.subarray(start, end + 1));
}

http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  try {
    if (req.method === 'OPTIONS') { res.writeHead(204, CORS); return res.end(); }
    if (url.pathname.startsWith('/api/')) return await api(req, res, url);
    const mm = /^\/media\/([a-f0-9]{24})$/.exec(url.pathname);
    if (mm) return media(req, res, mm[1]);
    const am = /^\/audio\/(g_[a-z0-9]+)\.mp3$/.exec(url.pathname);
    if (am && AUDIO[am[1]]) return audio(req, res, AUDIO[am[1]]);
    if (url.pathname === '/' || url.pathname === '/index.html') {
      res.writeHead(200, {'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache'}); return res.end(PAGE);
    }
    send(res, 404, {error: 'not found'});
  } catch (e) { send(res, e.code >= 400 && e.code < 600 ? e.code : 500, {error: e.code ? e.message : 'Something went wrong'}); }
}).listen(PORT, HOST, () => console.log(`Random Reels is running on http://localhost:${PORT}`));

// the website itself (index.html), packed in so this is the only file you need
const PAGE = Buffer.from('', 'base64');
// Original music and sound effects (MP3), served from /audio/<id>.mp3
const AUDIO = {};
AUDIO['g_dart'] = Buffer.from('', 'base64');
AUDIO['g_alarm'] = Buffer.from('', 'base64');
